import{_ as a,c as t,o as s,ag as i}from"./chunks/framework.DuVOYUUM.js";const u=JSON.parse('{"title":"Running The Project","description":"","frontmatter":{},"headers":[],"relativePath":"projects/igvc-2026/software/environment-setup/first-run.md","filePath":"projects/igvc-2026/software/environment-setup/first-run.md","lastUpdated":1790647345000}'),o={name:"projects/igvc-2026/software/environment-setup/first-run.md"};function n(l,e,r,c,p,d){return s(),t("div",null,e[0]||(e[0]=[i(`<h1 id="running-the-project" tabindex="-1">Running The Project <a class="header-anchor" href="#running-the-project" aria-label="Permalink to &quot;Running The Project&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Ros 2 desktop and optional tools must be installed using <a href="./">this tutorial</a>.</li></ul><h2 id="environment-setup" tabindex="-1">Environment Setup <a class="header-anchor" href="#environment-setup" aria-label="Permalink to &quot;Environment Setup&quot;">​</a></h2><ol><li><p>First, fork our <a href="https://github.com/oaklandrobotics/ros_ora26" target="_blank" rel="noreferrer">git repository</a> by clicking the &#39;fork&#39; button. Now you effectively have a copy of the repository on your own GitHub account.</p></li><li><p>We will now create a folder to store our forked project on our local computer. To do this, create a folder named <code>ros_ora26</code>. Then create folder named <code>src</code> inside of it. You can also use this command to create both folders at the same time in your home directory:</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p ~/ros_ora26/src</span></span></code></pre></div><ol start="3"><li>Clone the repository by clicking the green &#39;code&#39; button; then copy the URL given in the box. From inside of the <code>~/ros_ora26/</code> folder(<code>cd ~/ros_ora26</code>), run this command to clone your fork into the <code>src/</code> folder:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone &lt;your-copied-url&gt; src</span></span></code></pre></div><ol start="4"><li>Now, enter this source command to add Ros 2 shell variables and configuration to your shell environment: (Tip: You can add this command to your <code>~/.bashrc</code> file to run automatically on every new terminal/shell.)</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source /opt/ros/jazzy/setup.bash</span></span></code></pre></div><ol start="5"><li>Ros 2 uses a tool called rosdep to handle project dependencies. These are packages of pre-made code that provide extra functionality for the project. Run the following commands to setup rosdep and install Ros 2 dependencies:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo rosdep init</span></span></code></pre></div><p>(Note: The <code>rosdep init</code> command only needs to be run once per system installation of the rosdep tool.)</p><ul><li>Update the repository lists:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rosdep update</span></span></code></pre></div><ul><li>Install project specific dependencies:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rosdep install -i --from-path src -y</span></span></code></pre></div><ol start="6"><li>Ros 2 uses the Colcon build tool to compile project packages. Use this command to build:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>colcon build --symlink-install --cmake-args -DCMAKE_BUILD_TYPE=Release</span></span></code></pre></div><ul><li><code>--symlink-install</code> flag allows us to change project files without needing to rebuild the project. (Note: Any time a new package/file is introduced to the project, the project must be rebuilt)</li><li><code>--cmake-args -DCMAKE_BUILD_TYPE=Release</code> Option enables compiler optimizations to improve performance. (Note: This can make debugging line-by-line more difficult as the compiled binary code is altered/optimized when built.)</li></ul><ol start="7"><li>The build process creates another source file with shell variables and configuration specific to the build. Use this command to apply them:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source install/setup.bash</span></span></code></pre></div><ol start="8"><li>We can now run the project with this command:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch ora_launch sim.launch.yaml</span></span></code></pre></div><ul><li>Alternatively, you can use the generic version of this command:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch &lt;path-to-launch-file&gt;</span></span></code></pre></div><h2 id="rebuilding-the-project" tabindex="-1">Rebuilding the Project <a class="header-anchor" href="#rebuilding-the-project" aria-label="Permalink to &quot;Rebuilding the Project&quot;">​</a></h2><p>If you wish to perform a complete rebuild the project or build a different version of the project; we recommend this process:</p><ol><li>Remove the build folders created by Colcon with this command:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -rf build/ install/ log/</span></span></code></pre></div><ol start="2"><li><p>We recommend you close and re-open a new terminal to clear all shell variables or configurations created for the previous project build.</p></li><li><p>Re-source your new shell/terminal using the following command: (Note: You can add this command to your <code>~/.bashrc</code> file to run it automatically for every new shell/terminal)</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source /opt/ros/jazzy/setup.bash</span></span></code></pre></div><ol start="4"><li>Now, repeat steps 5-8 from the Environment Setup section to install dependencies, build with Colcon, and run the project.</li></ol><h2 id="extra-notes" tabindex="-1">Extra Notes <a class="header-anchor" href="#extra-notes" aria-label="Permalink to &quot;Extra Notes&quot;">​</a></h2><h3 id="nvidia-egl-libraries" tabindex="-1">Nvidia EGL Libraries <a class="header-anchor" href="#nvidia-egl-libraries" aria-label="Permalink to &quot;Nvidia EGL Libraries&quot;">​</a></h3><p>If you have an Nvidia GPU and see warnings similar to this in the terminal when running the project:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[component_container-4] pci id for fd 95: 10de:2182, driver (null)</span></span>
<span class="line"><span>[component_container-4] pci id for fd 96: 10de:2182, driver (null)</span></span>
<span class="line"><span>[component_container-4] libEGL warning: egl: failed to create dri2 screen</span></span>
<span class="line"><span>[component_container-4] libEGL warning: pci id for fd 94: 10de:2182, driver (null)</span></span></code></pre></div><p>This is caused by misconfiguration with the Nvidia EGL vendor library. We can attempt to fix this by specifying the library path. Try adding this line to the end of your <code>~.bashrc</code> to fix it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export __EGL_VENDOR_LIBRARY_FILENAMES=/usr/share/glvnd/egl_vendor.d/10_nvidia.json</span></span></code></pre></div><p>Now source your new bashrc with the command: <code>source ~/.bashrc</code></p><hr>`,41)]))}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
